public final class Deduplicator {
    private final Set<Key> seen = new HashSet<Key>();
    public synchronized boolean claim(String tenant, String eventId) {
        if (tenant == null || tenant.isEmpty() || eventId == null || eventId.isEmpty()) {
            throw new IllegalArgumentException("tenant and eventId are required");
        }
        return seen.add(new Key(tenant, eventId));
    }
    private static final class Key {
        private final String tenant;
        private final String eventId;
        Key(String tenant, String eventId) {
            this.tenant = tenant;
            this.eventId = eventId;
        }
        @Override
        public boolean equals(Object obj) {
            if (!(obj instanceof Key)) {
                return false;
            }
            Key other = (Key) obj;
            return tenant.equals(other.tenant) && eventId.equals(other.eventId);
        }
        @Override
        public int hashCode() {
            return tenant.hashCode() * 31 + eventId.hashCode();
        }
    }
}

