import java.util.*;
public class T {
    static VerificationStatus.Run run(String rev, long t, Boolean p) {
        return new VerificationStatus.Run(rev, t, p);
    }
    static void check(boolean b, String m){ if(!b) throw new AssertionError(m); }
    public static void main(String[] a) {
        // older passing run must not override newer failure on same revision
        check(!VerificationStatus.isCurrentSuccess(
            Arrays.asList(run("r1", 100L, Boolean.TRUE), run("r1", 200L, Boolean.FALSE)), "r1"),
            "older pass vs newer failure");
        // reversed input order: latest still wins
        check(!VerificationStatus.isCurrentSuccess(
            Arrays.asList(run("r1", 200L, Boolean.FALSE), run("r1", 100L, Boolean.TRUE)), "r1"),
            "order independence failure");
        check(VerificationStatus.isCurrentSuccess(
            Arrays.asList(run("r1", 100L, Boolean.FALSE), run("r1", 200L, Boolean.TRUE)), "r1"),
            "latest success wins");
        // different revision must not override
        check(!VerificationStatus.isCurrentSuccess(
            Arrays.asList(run("r1", 300L, Boolean.TRUE), run("r2", 400L, Boolean.FALSE)), "r1"),
            "other revision ignored");
        check(VerificationStatus.isCurrentSuccess(
            Arrays.asList(run("r1", 100L, Boolean.TRUE), run("r2", 999L, Boolean.FALSE)), "r1"),
            "success unaffected by newer other-revision run");
        // latest unknown is not success
        check(!VerificationStatus.isCurrentSuccess(
            Arrays.asList(run("r1", 100L, Boolean.TRUE), run("r1", 200L, null)), "r1"),
            "latest unknown not success");
        // empty / no runs for revision
        check(!VerificationStatus.isCurrentSuccess(Collections.<VerificationStatus.Run>emptyList(), "r1"),
            "empty evidence");
        check(!VerificationStatus.isCurrentSuccess(
            Arrays.asList(run("r2", 500L, Boolean.TRUE)), "r1"),
            "no runs for revision");
        System.out.println("ALL PASS");
    }
}
EOF
